// In production: exec nmap via n8n Execute Command node
// nmap -sV -p 1-65535 --open -T4 {ip} -oJ /tmp/scan.json
const assets=$input.all().map(i=>i.json);
// Return mock scan structure — replace with actual nmap JSON parsing
return assets.map(a=>({json:{asset_id:a.asset_id,ip:a.ip_address,scan_time:new Date().toISOString(),
  open_ports:[{port:443,service:'https',version:'nginx/1.24'},{port:80,service:'http',version:'nginx/1.24'}]
}}));

const current=$('Simulate Nmap Scan').all().map(i=>i.json);
const baseline=$('Get Previous Baseline').all().map(i=>({...i.json,ports:JSON.parse(i.json.open_ports_json||'[]')}));
const changes=[];
for(const scan of current){
  const prev=baseline.find(b=>b.asset_id===scan.asset_id);
  const prevPorts=(prev?.ports||[]).map(p=>p.port);
  const currPorts=scan.open_ports.map(p=>p.port);
  const newPorts=currPorts.filter(p=>!prevPorts.includes(p));
  const closedPorts=prevPorts.filter(p=>!currPorts.includes(p));
  if(newPorts.length>0) changes.push({asset_id:scan.asset_id,ip:scan.ip,type:'NEW_PORT',ports:newPorts,severity:'High'});
  if(closedPorts.length>0) changes.push({asset_id:scan.asset_id,ip:scan.ip,type:'CLOSED_PORT',ports:closedPorts,severity:'Info'});
}
return[{json:{scan_date:new Date().toISOString(),assets_scanned:current.length,changes,change_count:changes.length,new_exposures:changes.filter(c=>c.type==='NEW_PORT').length}}];

